from collections import Counter

def transform(grid):
    H, W = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comp_id = [[-1]*W for _ in range(H)]
    comps = []
    for r in range(H):
        for c in range(W):
            if comp_id[r][c] == -1:
                v = grid[r][c]
                cid = len(comps)
                stack = [(r, c)]
                comp_id[r][c] = cid
                cells = []
                while stack:
                    x, y = stack.pop()
                    cells.append((x, y))
                    for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx, ny = x+dx, y+dy
                        if 0 <= nx < H and 0 <= ny < W and comp_id[nx][ny] == -1 and grid[nx][ny] == v:
                            comp_id[nx][ny] = cid
                            stack.append((nx, ny))
                comps.append((v, cells))
    out = [row[:] for row in grid]
    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            nbrs = [(r+dx, c+dy) for dx, dy in ((1,0),(-1,0),(0,1),(0,-1))]
            nbrs = [(x, y) for x, y in nbrs if 0 <= x < H and 0 <= y < W]
            if any(grid[x][y] == v for x, y in nbrs):
                continue
            chosen = None
            for cv, cells in comps:
                if cv == v or cv == bg:
                    continue
                if not any(grid[x][y] == cv for x, y in nbrs):
                    continue
                rs = [x for x, _ in cells]
                cs = [y for _, y in cells]
                nr0, nr1 = min(min(rs), r), max(max(rs), r)
                nc0, nc1 = min(min(cs), c), max(max(cs), c)
                if (nr1-nr0+1)*(nc1-nc0+1) == len(cells)+1:
                    chosen = cv
                    break
            if chosen is None:
                vals = [grid[x][y] for x, y in nbrs]
                if vals and all(t == vals[0] for t in vals) and vals[0] != v:
                    chosen = vals[0]
            if chosen is None:
                chosen = bg
            out[r][c] = chosen
    return out
